function run(cpf){
  let Soma = 0
  let Resto = 0


  let strCPF = cpf.replace(/[^\w\s]/gi, "");
  let blacklist = [];
  for (let index = 0; index < 10; index++) {
    const mask = `${index}${index}${index}${index}${index}${index}${index}${index}${index}${index}${index}`;
    blacklist.push(mask);
  }
  const isBlocked = blacklist.filter(item => item === strCPF);
  if (isBlocked.length) return false;

  for (var i = 1; i <= 9; i++)
    Soma = Soma + parseInt(strCPF.substring(i - 1, i)) * (11 - i);
  Resto = (Soma * 10) % 11;

  if (Resto === 10 || Resto === 11) Resto = 0;
  if (Resto !== parseInt(strCPF.substring(9, 10))) return false;

  Soma = 0;
  for (i = 1; i <= 10; i++)
    Soma = Soma + parseInt(strCPF.substring(i - 1, i)) * (12 - i);
  Resto = (Soma * 10) % 11;

  if (Resto === 10 || Resto === 11) Resto = 0;
  if (Resto !== parseInt(strCPF.substring(10, 11))) return false;
  return cpf;

}
