        }

        if (IsoDateToBR(data, false) === diasDisponiveis[i - 1]) {      
            diasDisponiveis[i] = IsoDateToBR(data, true);               
            continue;                                                   
        }

        diasDisponiveis[i] = IsoDateToBR(data, false);                  
    }

    let hours = new Date().getHours();

    // ANTES DAS 12h → amanhã começa só à tarde
