function run(input) {
    let uf = input;
    let dias = 6;                                                       //Seta o número de dias a ser salvo
    let diasDisponiveis = []                                            //Cria um Objeto(Array) pra armazenar os dias disponíveis

    let data = new Date();                                              //Cria um objeto de Data para no dia de hoje

    let horarioParaChecar = new Date();                                 // Para testar horários antes de 12h use '2023-12-13T08:24:00' no construtor
    if (uf == "SP") {
        //data = new Date('2024-04-02T00:00:00');
        data = new Date();
    }
    // Se quiser testar com horários depois basta usar '2023-12-13T12:24:00'
    data = zeraHorario(data);                                           //Zera os horários para não haver erros no laço de repetição

    for (let i = 0; i <= dias; i++) {

        data = addDays(data, 1);                                        //Adiciona um dia a cada iteração do laço de repetição

        if (i == 0 && !(isSunday(data))) {                               //Verifica se é a primeira iteração e se não é domingo
            diasDisponiveis[i] = IsoDateToBR(data, true);               //Adiciona um dia a mais na váriavel e salva no objeto
        }

        if (isSunday(data)) {                                           //Verifica se é domingo
            diasDisponiveis[i] = IsoDateToBR(data, true);               //Adiciona um dia a mais na váriavel e salva no objeto
            continue;                                                   //Pula já para a próxima iteração
        }

        if (IsoDateToBR(data, false) === diasDisponiveis[i - 1]) {      //Verifica se a data que vai ser salva é igual a que foi salva anteriormente
            diasDisponiveis[i] = IsoDateToBR(data, true)                //Adiciona um dia a mais na váriavel e salva no objeto
            continue;
        }

        diasDisponiveis[i] = IsoDateToBR(data, false);                  //Salva no objeto o dia disponível
    }

    return retornoDeDatas(horarioParaChecar.getHours(), diasDisponiveis);
    //Retorna o objeto com os dias disponíveis
}

function isSunday(date) {                                               //Função pra verificar se o dia é domingo
    return date.getDay() === 0;                                         //0 = domingo
}

function addDays(date, days) {                                          //Função pra adicionar dias
    date.setDate(date.getDate() + days);
    return date;
}

function IsoDateToBR(date, condition) {                                 //Função pra transformar a data em formato BR
    const daysOfWeek = ["(dom)", "(seg)", "(ter)", "(qua)", "(qui)", "(sex)", "(sab)"];

    if (condition) {
        date = addDays(date, 1);                                        //Adiciona mais um dia
    }

    const dayName = daysOfWeek[date.getDay()];                          //Agora calcula o nome do dia no momento certo
    return `${padZero(date.getDate())}/${padZero(date.getMonth() + 1)} - ${dayName}`;
}

function zeraHorario(date) {                                            //Função para zerar os horários do objeto Date
    date.setUTCHours(0);
    date.setUTCMilliseconds(0);
    date.setUTCMinutes(0);
    date.setUTCSeconds(0);
    return date;
}

function retornoDeDatas(hours, diasDisponiveis) {
    // ANTES DAS 12h → começa amanhã À TARDE
    if (hours < 12) {
        return [
            { "id": `${diasDisponiveis[0]} - 13h30 a 18h00`, "title": `${diasDisponiveis[0]} - 13h30 a 18h00` },
            { "id": `${diasDisponiveis[1]} - 08h30 a 12h30`, "title": `${diasDisponiveis[1]} - 08h30 a 12h30` },
            { "id": `${diasDisponiveis[1]} - 13h30 a 18h00`, "title": `${diasDisponiveis[1]} - 13h30 a 18h00` },
