function run(wwthreadsresponse, wwthread, wwlastmessageid, wwassistant, wwlastassistant, chatgptResponse) {
    wwthreadsresponse = JSON.parse(wwthreadsresponse)

    if (wwassistant !== wwlastassistant) {
        return {}
    }

    if (typeof chatgptResponse === 'string') {
        return { thread: wwthread, skillResponse: chatgptResponse }
    }

    const items = wwthreadsresponse && wwthreadsresponse.resource && wwthreadsresponse.resource.items
    if (Array.isArray(items)) {
        const lastItemUserMessageIndex = items.findIndex((i) => i.direction === 'received')
        if (lastItemUserMessageIndex === -1) {
            return { thread: wwthread }
        } else {
            const sentMessages = items.slice(0, lastItemUserMessageIndex)
            if (sentMessages.length) {
                return { thread: wwthread, skillResponse: sentMessages.map((m) => messageToText(m.content)).join('\n') }
            }
        }
    }

    return { thread: wwthread }
}

