const __s = function (x) { return x === undefined || x === null ? "" : (typeof x === "object" ? JSON.stringify(x) : String(x)); };
function run() {
    let dias = 5;                                                       //Seta o número de dias a ser salvo
    let diasDisponiveis = [];                                            //Cria um Objeto(Array) pra armazenar os dias disponíveis

    let data = new Date();                                              //Cria um objeto de Data para no dia de hoje

    data = zeraHorario(data);                                           //Zera os horários para não haver erros no laço de repetição

    for (let i = 0; i <= dias; i++) {

        data = addDays(data, 1);                                        //Adiciona um dia a cada iteração do laço de repetição

        if (i == 0 && !(isSunday(data))) {                               //Verifica se é a primeira iteração e se não é domingo
            diasDisponiveis[i] = IsoDateToBR(data, true);               //Adiciona um dia a mais na váriavel e salva no objeto
        }

        if (isSunday(data)) {                                           //Verifica se é domingo
            diasDisponiveis[i] = IsoDateToBR(data, true);               //Adiciona um dia a mais na váriavel e salva no objeto
            continue;                                                   //Comando pra pular o que tem abaixo no laço de repetição e pular já para a próxima iteração
        }

        if (IsoDateToBR(data, false) === diasDisponiveis[i - 1]) {          //Verifica se a data que vai ser salva é igual a que foi salva anteriormente
            diasDisponiveis[i] = IsoDateToBR(data, true)                //Adiciona um dia a mais na váriavel e salva no objeto
            continue;                                                   //Comando pra pular o que tem abaixo no laço de repetição e pular já para a próxima iteração
        }

        diasDisponiveis[i] = IsoDateToBR(data, false);                  //Salva no objeto o dia disponível
    }


    return [
        `${diasDisponiveis[0]} - manhã`,
        `${diasDisponiveis[0]} - tarde`,
        `${diasDisponiveis[1]} - manhã`,
        `${diasDisponiveis[1]} - tarde`,
        `${diasDisponiveis[2]} - manhã`,
        `${diasDisponiveis[2]} - tarde`,
        `${diasDisponiveis[3]} - manhã`,
        `${diasDisponiveis[3]} - tarde`,
        `${diasDisponiveis[4]} - manhã`,
        `${diasDisponiveis[4]} - tarde`
    ]
