        if (!input) {
            return false;
        }

        // Remove tudo que não for número
        const telefone = String(input).replace(/\D/g, "");

        // Deve possuir exatamente 10 ou 11 dígitos (DDD + telefone)
        if (telefone.length !== 10 && telefone.length !== 11) {
            return false;
        }

        const ddd = telefone.substring(0, 2);
        const numero = telefone.substring(2);

        // DDD válido (11 a 99)
        const dddNumero = parseInt(ddd, 10);
        if (dddNumero < 11 || dddNumero > 99) {
            return false;
        }

        // Celular: 9 dígitos começando com 9
        if (numero.length === 9) {
            if (!/^9\d{8}$/.test(numero)) {
                return false;
            }
        }

        // Fixo: 8 dígitos começando entre 2 e 5
        if (numero.length === 8) {
            if (!/^[2-5]\d{7}$/.test(numero)) {
                return false;
            }
        }

        return telefone;
    } catch (e) {
        return false;
    }
}
